import '../components/sw-card';
import '../components/sw-button';
import { describeError, patch } from '../api/client';
import { getSettings } from '../api/media';
import { invalidateSettings } from '../api/prefs';
import { isApi } from '../api/session';
import { DIRECTION_DEFAULT, DIRECTION_LABEL, DIRECTION_LETTER, DIRECTIONS, homeSettingsOf, SIDE_LABEL, SIDES, type Direction, type Side } from '../api/home';
import { SkinController } from '../design/skin';
import { BULK_IDLE, BULK_IDLE_DEFAULT, FLOOR_TITLE_LINES, FLOOR_TITLE_LINES_DEFAULT, LONG_LISTS, LONG_LISTS_DEFAULT, screenDisplayOf, type BulkIdle, type FloorTitleLines, type InfoStyle, type LongLists } from '../api/screen-display';
import { demoScreenOverrides, homeScreenOf, screenFormBody } from '../api/home-screen';
import { getDevicesTree } from '../api/devices';
import { loadTree as loadCatalogTree } from '../api/catalog';
import { multiBuildingOn } from '../api/mapping';
import { hs } from '../i18n/home-screen';
import './home-screen-options';
import type { HomeScreenForm, OptionsArea } from './home-screen-options';
import { bubbleChrome } from '../styles/bubble-chrome';

/** A schematic of each direction (the mockup's three layouts): the widgets in the accent colour, the summary tiles, the floors. */
function thumb(d: Direction, side: Side): TemplateResult {
  const w = (x: number, y: number, ww: number, hh: number, cls = 'wg') => svg`<rect class=${cls} x=${x} y=${y} width=${ww} height=${hh} rx="3"/>`;
  const kpis = (x: number, y: number, ww: number) => svg`${[0, 1, 2, 3, 4, 5].map((i) => w(x + (i * ww) / 6, y, ww / 6 - 2, 7, 'kp'))}`;
  if (d === 'a') {
    return svg`${w(4, 4, 30, 22)}${w(37, 4, 30, 22)}${w(70, 4, 22, 22)}${w(95, 4, 21, 22)}${kpis(4, 30, 112)}
      ${w(4, 41, 24, 34, 'fl')}${w(31, 41, 42, 34, 'fl')}${w(76, 41, 40, 34, 'fl')}`;
  }
  if (d === 'b') {
    const sx = side === 'end' ? 4 : 84;
    const mx = side === 'end' ? 38 : 4;
    return svg`${kpis(mx, 4, 78)}${w(sx, 4, 32, 14)}${w(sx, 21, 32, 22)}${w(sx, 46, 32, 12)}${w(sx, 61, 32, 14)}
      ${w(mx, 15, 34, 28, 'fl')}${w(mx + 38, 15, 40, 28, 'fl')}${w(mx, 46, 78, 29, 'fl')}`;
  }
  return svg`${w(4, 4, 28, 14)}${w(35, 4, 28, 14)}${w(66, 4, 24, 14)}${w(93, 4, 23, 14)}${kpis(4, 22, 112)}
    ${w(4, 34, 34, 41, 'fl')}${w(41, 34, 34, 41, 'fl')}${w(78, 34, 38, 41, 'fl')}`;
}

/**
 * הגדרות › חשמל והתקנים › מסך ראשי (home redesign, owner decisions 2026-09-30): the installation's direction of the home
 * screen - a: מרכז בקרה (the default), b: לוח צד, c: מצומצם - each with a live preview thumbnail, and the side of b's column.
 * Applies to everyone without a personal choice (החשבון שלי › המסך שלי, for a holder of screen.personalize). The widgets
 * themselves - which, how big, in what order, fed by which entity - are edited on the screen ("עריכת המסך הראשי" of the user
 * menu). Saved at once (system.configure, audited); read-only for anyone else.
 */
@customElement('system-home-screen')
export class SystemHomeScreen extends LitElement {
  /** 0.1.157: the bubble skin's chrome keys on the host's data-skin (styles/bubble-chrome.ts). */
  readonly bubbleSkin = new SkinController(this);
  @state() private direction: Direction = DIRECTION_DEFAULT;
  @state() private side: Side = 'end';
  /** HOME-295: every display choice of the home screen (home.screen, the info row home.info_style, the view devices.default_view). */
  @state() private form: HomeScreenForm = { screen: homeScreenOf(isApi() ? null : demoScreenOverrides()), info: 'auto', view: 'cards' };
  /** The areas for the per-area quick actions (the tree this user may read; none = the editor is not shown). */
  @state() private areas: OptionsArea[] = [];
  @state() private buildings: { id: string; name: string }[] = [];
  /** POLISH-CONTROL-297 (owner decisions on the worst-case report, 2026-10-27): the floor-name clamp, huge lists paged or scrolled, idle
   * bulk buttons disabled or clickable (the bulk item stays open for the owner's design talk). */
  @state() private floorTitleLines: FloorTitleLines = FLOOR_TITLE_LINES_DEFAULT;
  @state() private longLists: LongLists = LONG_LISTS_DEFAULT;
  @state() private bulkIdle: BulkIdle = BULK_IDLE_DEFAULT;
  @state() private canEdit = false;
  @state() private busy = false;
  @state() private message = '';
  @state() private error = '';

  static styles = [css`
    :host {
      display: block;
    }
    .opts {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
      gap: 12px;
    }
    button.opt {
      all: unset;
      box-sizing: border-box;
      display: flex;
      flex-direction: column;
      gap: 8px;
      padding: 10px;
      border: 2px solid var(--sw-border);
      border-radius: var(--sw-r-md);
      background: var(--sw-surface);
      cursor: pointer;
    }
    button.opt[aria-pressed='true'] {
      border-color: var(--sw-accent);
      background: var(--sw-accent-soft);
    }
    button.opt:disabled {
      cursor: default;
      opacity: 0.75;
    }
    button.opt:focus-visible,
    .seg button:focus-visible {
      outline: var(--sw-focus-w) solid var(--sw-focus);
      outline-offset: 2px;
    }
    svg.thumb {
      inline-size: 100%;
      block-size: auto;
      aspect-ratio: 120 / 80;
      background: var(--sw-bg);
      border: 1px solid var(--sw-border);
      border-radius: var(--sw-r-sm);
    }
    svg.thumb .wg {
      fill: var(--sw-accent);
      opacity: 0.85;
    }
    svg.thumb .kp {
      fill: var(--sw-border-strong);
    }
    svg.thumb .fl {
      fill: var(--sw-surface-3);
      stroke: var(--sw-border-strong);
      stroke-width: 0.6;
    }
    .cap {
      display: flex;
      align-items: baseline;
      gap: 6px;
      font-weight: var(--sw-fw-semibold);
    }
    .cap .let {
      color: var(--sw-accent-text);
    }
    .row {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
      margin-block-start: 12px;
    }
    .seg {
      display: inline-flex;
      gap: 2px;
      padding: 3px;
      background: var(--sw-surface-3);
      border-radius: var(--sw-r-md);
    }
    .seg button {
      all: unset;
      box-sizing: border-box;
      min-block-size: 34px;
      padding: 0 14px;
      display: inline-flex;
      align-items: center;
      border-radius: var(--sw-r-sm);
      color: var(--sw-text-2);
      font-weight: var(--sw-fw-medium);
      cursor: pointer;
    }
    .seg button[aria-pressed='true'] {
      background: var(--sw-seg-key, var(--sw-surface));
      color: var(--sw-seg-key-ink, var(--sw-accent-text));
      box-shadow: var(--sw-seg-thumb-shadow, var(--sw-shadow-1));
    }
    .ok {
      color: var(--sw-live);
      font-size: var(--sw-fs-sm);
    }
    .err {
      color: var(--sw-danger);
      font-size: var(--sw-fs-sm);
    }
    .muted {
      color: var(--sw-text-3);
      font-size: var(--sw-fs-sm);
    }
    .hs-h {
      margin: 18px 0 8px;
      font-size: var(--sw-fs-md);
      color: var(--sw-heading);
    }
  `, bubbleChrome];

  connectedCallback() {
    super.connectedCallback();
    if (!isApi()) return;
    void getSettings()
      .then((r) => {
        this.canEdit = r.can_edit;
        const h = homeSettingsOf(r.settings as unknown as Record<string, unknown>);
        this.direction = h.direction;
        this.side = h.side;
        const raw = r.settings as unknown as Record<string, unknown>;
        const sd = screenDisplayOf(raw);
        this.form = { screen: homeScreenOf(raw['home.screen']), info: sd.infoStyle, view: raw['devices.default_view'] === 'tiles' ? 'tiles' : 'cards' };
        this.floorTitleLines = sd.floorTitleLines;
        this.longLists = sd.longLists;
        this.bulkIdle = sd.bulkIdle;
      })
      .catch(() => undefined);
    void getDevicesTree()
      .then((t) => (this.areas = t.floors.flatMap((f) => f.areas.map((a) => ({ id: a.area_id, name: a.name, floor: f.name, counts: a.counts })))))
      .catch(() => (this.areas = []));
    // MULTIBUILDING-HOME-2330: the site options show only on a site of several buildings
    // MAPPING-ASSIST-2330: and only while the multi-building view is switched on (owner 31.10: off by default)
    void Promise.all([multiBuildingOn(), loadCatalogTree()])
      .then(([on, c]) => (this.buildings = on ? c.sites.flatMap((s) => (s.buildings ?? []).map((b) => ({ id: b.id, name: b.name }))) : []))
      .catch(() => (this.buildings = []));
  }

  private async save(change: { direction?: Direction; side?: Side; info?: InfoStyle }) {
    if (!this.canEdit || this.busy) return;
    const before = { direction: this.direction, side: this.side };
    this.direction = change.direction ?? this.direction;
    this.side = change.side ?? this.side;
    this.busy = true;
    this.error = '';
    try {
      const body: Record<string, string> = {};
      if (change.direction) body['home.direction'] = change.direction;
      if (change.side) body['home.side'] = change.side;
      await patch('settings', body);
      invalidateSettings();
      this.message = 'המסך הראשי נשמר';
      setTimeout(() => (this.message = ''), 2500);
    } catch (err) {
      this.direction = before.direction;
      this.side = before.side;
      this.error = describeError(err);
    } finally {
      this.busy = false;
    }
  }

  /** POLISH-CONTROL-297: one of the three worst-case choices, saved at once. */
  private async saveChoice(key: 'home.floor_title_lines' | 'ui.long_lists' | 'home.bulk_idle', value: string) {
    if (!this.canEdit || this.busy || !isApi()) return;
    const before = { floorTitleLines: this.floorTitleLines, longLists: this.longLists, bulkIdle: this.bulkIdle };
    if (key === 'home.floor_title_lines') this.floorTitleLines = value as FloorTitleLines;
    else if (key === 'ui.long_lists') this.longLists = value as LongLists;
    else this.bulkIdle = value as BulkIdle;
    this.busy = true;
    this.error = '';
    try {
      await patch('settings', { [key]: value });
      invalidateSettings();
      this.message = hs('saved');
      setTimeout(() => (this.message = ''), 2500);
    } catch (err) {
      this.floorTitleLines = before.floorTitleLines;
      this.longLists = before.longLists;
      this.bulkIdle = before.bulkIdle;
      this.error = describeError(err);
    } finally {
      this.busy = false;
    }
  }

  /** A settings row with a segmented choice (the same row shape as the board side). */
  private choiceRow<T extends string>(label: string, attr: string, items: readonly T[], labels: Record<T, string>, value: T, ro: boolean, onPick: (v: T) => void): TemplateResult {
    return html`<div class="row" data-home-choice=${attr}><span>${label}</span><span class="seg" role="group" aria-label=${label}>${items.map((v) => html`<button type="button" data-home-choice-option=${v} aria-pressed=${String(value === v)} ?disabled=${ro || this.busy} @click=${() => onPick(v)}>${labels[v]}</button>`)}</span></div>`;
  }

  /** HOME-295: one change of the options form, saved at once (only the keys that changed). */
  private async saveForm(next: HomeScreenForm) {
    if (!this.canEdit || this.busy || !isApi()) return;
    const before = this.form;
    const body = screenFormBody(before, next);
    if (!Object.keys(body).length) return;
    this.form = next;
    this.busy = true;
    this.error = '';
    try {
      const r = await patch<{ settings: Record<string, unknown> }>('settings', body);
      invalidateSettings();
      if (r?.settings?.['home.screen']) this.form = { ...next, screen: homeScreenOf(r.settings['home.screen']) };
      this.message = hs('saved');
      setTimeout(() => (this.message = ''), 2500);
    } catch (err) {
      this.form = before;
      this.error = describeError(err);
    } finally {
      this.busy = false;
    }
  }

  render() {
    const ro = !this.canEdit || !isApi();
    return html`<sw-card heading="מסך ראשי" subheading="הכיוון של מסך ״ראשי״ לכל המשתמשים במתקן" data-home-screen-settings>
      <div class="opts" role="group" aria-label="כיוון המסך הראשי">
        ${DIRECTIONS.map(
          (d) => html`<button type="button" class="opt" data-home-dir-option=${d} aria-pressed=${String(this.direction === d)} ?disabled=${ro || this.busy} @click=${() => void this.save({ direction: d })}>
            <svg class="thumb" viewBox="0 0 120 80" aria-hidden="true" data-home-dir-thumb=${d}>${thumb(d, this.side)}</svg>
            <span class="cap"><span class="let">${DIRECTION_LETTER[d]}</span>${DIRECTION_LABEL[d]}</span>
          </button>`,
        )}
      </div>
      ${this.direction === 'b'
        ? html`<div class="row"><span>צד הלוח</span><span class="seg" role="group" aria-label="צד הלוח">${SIDES.map((s) => html`<button type="button" data-home-side-option=${s} aria-pressed=${String(this.side === s)} ?disabled=${ro || this.busy} @click=${() => void this.save({ side: s })}>${SIDE_LABEL[s]}</button>`)}</span></div>`
        : nothing}
      <h3 class="hs-h" data-home-screen-options-heading>${hs('heading')}</h3>
      <home-screen-options .value=${this.form} .areas=${this.areas} .buildings=${this.buildings} ?editable=${!ro && !this.busy} @hs-change=${(e: CustomEvent<HomeScreenForm>) => void this.saveForm(e.detail)}></home-screen-options>
      ${this.choiceRow('שם קומה ארוך בכותרת כרטיס', 'floor-title-lines', FLOOR_TITLE_LINES, { '2': 'שתי שורות', '3': 'שלוש שורות', '1': 'שורה אחת עם ...' } as Record<FloorTitleLines, string>, this.floorTitleLines, ro, (v) => void this.saveChoice('home.floor_title_lines', v))}
      ${this.choiceRow('רשימות ארוכות מאוד', 'long-lists', LONG_LISTS, { paged: 'עמודים', scroll: 'גלילה מלאה' } as Record<LongLists, string>, this.longLists, ro, (v) => void this.saveChoice('ui.long_lists', v))}
      ${this.choiceRow('כפתור "כבה הכל" כשאין מה לכבות', 'bulk-idle', BULK_IDLE, { disabled: 'מושבת', enabled: 'לחיץ תמיד' } as Record<BulkIdle, string>, this.bulkIdle, ro, (v) => void this.saveChoice('home.bulk_idle', v))}
      <div class="row">
        <sw-button size="sm" icon="edit" data-home-edit-link @click=${() => (location.hash = '#/devices/building?edit=1')} ?disabled=${ro}>עריכת המסך הראשי</sw-button>
        ${this.message ? html`<span class="ok" role="status" data-home-message>${this.message}</span>` : nothing}
        ${this.error ? html`<span class="err" role="alert">${this.error}</span>` : nothing}
        ${ro ? html`<span class="muted">${isApi() ? 'שינוי ההגדרות דורש הרשאת מנהל מערכת.' : 'נתוני הדגמה: ההגדרות נשמרות רק מול השרת.'}</span>` : nothing}
      </div>
    </sw-card>`;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'system-home-screen': SystemHomeScreen;
  }
}
